//This method is sets values for generating pallete and gets the value of color on the basis of t
vec3 getPalette(float t)
{
    return palette(
    vec3( 0.3, 0.5, 0.5	),
    vec3(0.5, 0.4, 0.5),
    vec3(2.0, 1.0, 0.0	),
    vec3(0.50, 0.20, 0.25),
    t);
}
vec3 getRandomColor(float t)
{
    return vec3( sin(t + iTime) , sin(t ) + .33 , sin(t + iTime)+ .66);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord * 2.  - iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;
    vec3 col = vec3(0.);
    float c;
    vec3 rcol;

      for(float i=0. ; i < 4. ; i++)
      {
            uv = fract(uv * 1.3) - .5;

            //vec3 col = vec3(uv , 0);

            float d = length(uv) * exp(-length (uv0));

            //multiplying i for more variations depending on each iteration
            rcol = getPalette( length (uv0)  + iTime * .02 + i*.4);


            d = sin (d*8. + iTime*1.5) / 8.; //to draw a signed circle of radius .5
            d = abs (d); //to change negative values to positive ,, inside the circle
            c = d;
            //  c = step ( .01 , d);
            c = smoothstep ( .0 , 0.05 , d );
            c = .15 / c;

            c = pow(c , sin(iTime)/5. +1.2);


            col += rcol *c;
       }





    fragColor = vec4(col,1.0);
}

#define pi 3.1415926


//This methos is for creation of palette
vec3 palette(vec3 a , vec3 b, vec3 c , vec3 d, float t)
{
    return a + b*cos( 2.*pi*( c*t + d ));

    //a = y axis of wave
    //b = amplitude (height of wave)
    //c = frequency
    //d = (phase / 2*pi)

}
